#[derive(Clone, Debug)]
struct ChildNode {
    child_type: String,
    code: String,
    raw: Option<String>,
    minimact_path: Option<String>,
}

pub fn generate_children(children: &Vec<JSXChild>, component: &mut Component, indent: i32) -> Vec<ChildNode> {
    let mut result = vec![];
    let mut child_list = vec![];
    for child in children {
        match child {
            JSXElementChild::JSXText(text_node) => {
                {
                    let text = text_node.value.trim();
                    if !text.is_empty() {
                        child_list.push(ChildNode { child_type: "text".into(), code: format!("\"{}\"", escape_csharp_string(&text)), raw: Some(text.to_string()), minimact_path: text_node.minimact_path.clone() })
                    }
                }
            }
            Expr::JSXElement(element) => {
                {
                    child_list.push(ChildNode { child_type: "element".into(), code: Self::generate_jsx_element(&JSXNode::JSXElement(Box::new(Expr::JSXElement(element.clone()))), component, (indent + 1)), raw: None, minimact_path: element.minimact_path.clone() })
                }
            }
            JSXElementChild::JSXExprContainer(container) => {
                {
                    let expr = &*container.expr;
                    match &expr {
                        Expr::JSXEmptyExpression(expr) => {
                            continue;
                        }
                        _ => {}
                    }
                    match expr {
                        Expr::Ident(ident) => {
                            match &component.custom_hooks {
                                Some(custom_hooks) => {
                                    let hook_instance = custom_hooks.iter().find(|h| {
                                        (h.ui_var_name.as_ref() == Some(&ident.name));
                                    });
                                    match hook_instance {
                                        Some(hook) => {
                                            let hex_path = container.minimact_path.clone().unwrap_or_default();
                                            let wrapper_code = generate_custom_hook_wrapper(hook, &hex_path, component, indent);
                                            child_list.push(ChildNode { child_type: "element".into(), code: wrapper_code, raw: None, minimact_path: container.minimact_path.clone() });
                                            continue;
                                        }
                                        _ => {}
                                    }
                                }
                                _ => {}
                            }
                        }
                        _ => {}
                    }
                    let child_type = if Self::is_structural_jsx(expr) {
                        "element".to_string()
                    } else {
                        "expression".to_string()
                    };
                    child_list.push(ChildNode { child_type: child_type.into(), code: generate_jsx_expression(expr, component, indent), raw: None, minimact_path: container.minimact_path.clone() })
                }
            }
            Expr::JSXFragment(fragment) => {
                {
                    child_list.push(ChildNode { child_type: "element".into(), code: Self::generate_fragment(fragment, component, (indent + 1)), raw: None, minimact_path: fragment.minimact_path.clone() })
                }
            }
            _ => {
                {
                }
            }
        }
    }
    let mut i = 0;
    while (i < child_list.len()) {
        let is_text_or_expr = ((child_list[i].child_type == "text") || (child_list[i].child_type == "expression"));
        if (is_text_or_expr && ((i + 1) < child_list.len())) {
            let next_is_text_or_expr = ((child_list[(i + 1)].child_type == "text") || (child_list[(i + 1)].child_type == "expression"));
            if next_is_text_or_expr {
                let mut mixed_children = vec![child_list[i].clone()];
                let mut j = (i + 1);
                while ((j < child_list.len()) && (((child_list[j].child_type == "text") || (child_list[j].child_type == "expression")))) {
                    mixed_children.push(child_list[j].clone());
                    j += 1;
                }
                let mut interpolated_code = String::new();
                for child in &mixed_children {
                    if (child.child_type == "text") {
                        match &child.raw {
                            Some(raw) => {
                                interpolated_code.push_str(&escape_csharp_string(raw))
                            }
                            _ => {}
                        }
                    } else {
                        interpolated_code.push_str(&format!("{{({})}}", child.code))
                    }
                }
                result.push(ChildNode { child_type: "mixed".into(), code: format!("$\"{}\"", interpolated_code), raw: None, minimact_path: mixed_children[0].minimact_path.clone() });
                i = j;
                continue;
            }
        }
        result.push(child_list[i].clone());
        i += 1;
    }
    result
}

fn is_structural_jsx(expr: &Expr) -> bool {
    match &expr {
        Expr::JSXElement(_) | Expr::JSXFragment(_) => {
            true
        }
        _ => {
            false
        }
    }
}

fn generate_custom_hook_wrapper(hook_instance: &CustomHook, hex_path: &String, component: &Component, indent: i32) -> String {
    let namespace = &hook_instance.namespace;
    let class_name = &hook_instance.class_name;
    let params = &hook_instance.params;
    let state_code = if !params.is_empty() {
        let state_entries = params.iter().enumerate().map(|(index, param_code)| format("[\"_config.param{}\"] = {}", index, param_code)).collect::<Vec<_>>().join(", ");
        format!("new Dictionary<string, object> {{ {} }}", state_entries)
    } else {
        "new Dictionary<string, object>()".into()
    };
    let indent_str = "  ".repeat(indent);
    format!("new VComponentWrapper\n{}{{\\n{}  ComponentName = \"{}\",\n{}  ComponentType = \"{}\",\n{}  HexPath = \"{}\",\n{}  InitialState = {}\n{}}}", indent_str, indent_str, namespace, indent_str, class_name, indent_str, hex_path, indent_str, state_code, indent_str)
}

fn generate_component_wrapper(element: &JSXElement, parent_component: &mut Component, indent: i32) -> String {
    let attributes = &element.opening_element.attributes;
    let hex_path = element.minimact_path.clone().unwrap_or_default();
    let name_attr = attributes.iter().find(|attr| {
        if attr {
            (a.name.name == "name")
        } else {
            false
        }
    });
    let component_name = if name_attr {
        match &attr.value {
            Some(Lit::Str(lit)) => {
                String::from_utf8_lossy(lit.value.as_bytes())
            }
            _ => {
                panic!("[Lifted State] <Component> name attribute must be a string literal")
            }
        }
    } else {
        panic!("[Lifted State] <Component> element must have a \"name\" attribute")
    };
    let state_attr = attributes.iter().find(|attr| {
        if attr {
            (a.name.name == "state")
        } else {
            false
        }
    });
    let mut state_code = "new Dictionary<string, object>()".to_string();
    match state_attr {
        Some(JSXAttrOrSpread::JSXAttr(attr)) => {
            match &attr.value {
                Option::Some(JSXElementChild::JSXExprContainer(container)) => {
                    match &*container.expr {
                        Expr::Object(obj) => {
                            let properties = obj.properties.iter().filter_map(|prop| {
                                if prop {
                                    if &p.key {
                                        let value = generate_csharp_expression(&p.value, parent_component, 0);
                                        return Some(format("[\"{}\"] = {}", key.name, value));
                                    }
                                }
                                None;
                            }).collect::<Vec<_>>();
                            if !properties.is_empty() {
                                state_code = format!("new Dictionary<string, object> {{ {} }}", properties.join(", "))
                            }
                        }
                        _ => {}
                    }
                }
                _ => {}
            }
        }
        _ => {}
    }
    let child_components = element.children.iter().filter_map(|c| {
        if c {
            Some(el)
        } else {
            None
        }
    }).collect();
    if (child_components.is_empty() || (child_components.len() > 1)) {
        panic!("[Lifted State] <Component name=\"{}\"> must have exactly one child element", component_name)
    }
    let child_tag_name = &child_components[0].opening_element.name.name;
    println!("[Lifted State] ✅ Detected <Component name=\"{}\"> wrapping <{} />", component_name, child_tag_name);
    format!("new VComponentWrapper\n{{\\n    ComponentName = \"{}\",\n    ComponentType = \"{}\",\n    HexPath = \"{}\",\n    InitialState = {},\n    ParentComponent = this\n}}", component_name, child_tag_name, hex_path, state_code)
}

